#!/usr/bin/env python3
"""unescaped-constructor-functions.py: each row has a constructor function P of its own, used by `new P(1, "s")` in plain sight twice, and ONE MORE THING that a layout agreed ahead must survive or give up on. What is printed: own keys in order, every member, the prototype's identity, instanceof, constructor, JSON, for-in. Untyped JavaScript: every line as plain Bun's."""
BASE = 'function P$(a, b) { this.x = a; this.y = b; }'
ROWS = [
 ('nothing more', BASE, ''), ('called without new, on an object', BASE, 'const o = {}; P$.call(o, 3, "c"); see(o);'), ('called without new, this undefined', BASE, 'P$(3, "c");'), ('apply with arguments', BASE, 'const o = { z: 0 }; P$.apply(o, [4, "d"]); see(o);'),
 ('Reflect.construct', BASE, 'see(Reflect.construct(P$, [5, "e"]));'), ('Reflect.construct with another new.target', BASE, 'function Q$() {} Q$.prototype.q = 1; see(Reflect.construct(P$, [5, "e"], Q$));'), ('a bound constructor', BASE, 'see(new (P$.bind(null, 6))("f"));'), ('one of two constructors', BASE, 'function Q$(a) { this.y = a; this.w = 1; } for (const C of [P$, Q$]) see(new C(7, "g"));'), ('through a variable', BASE, 'let C = P$; see(new C(8, "h"));'), ('through a member', BASE, 'const h = { C: P$ }; see(new h.C(9, "i"));'), ('through an array', BASE, 'see(new [P$][0](9, "i"));'),
 ('fewer arguments, no parentheses', BASE, 'see(new P$(1)); see(new P$);'), ('more arguments', BASE, 'see(new P$(1, 2, 3, 4));'), ('a spread', BASE, 'see(new P$(...[1, "sp"]));'),
 ('a method added to the prototype late', BASE, 'const o = new P$(1, "m"); P$.prototype.sum = function () { return this.x + this.y; }; out.push(o.sum()); see(o);'), ('a data member on the prototype', BASE, 'P$.prototype.z = "proto"; const o = new P$(1, "m"); out.push(o.z); see(o);'), ('the prototype replaced', BASE, 'const before = new P$(1, "m"); P$.prototype = { tag: "new proto" }; const after = new P$(2, "n"); out.push(before.tag, after.tag, before instanceof P$, after instanceof P$); see(after);'), ('the prototype is null', BASE, 'P$.prototype = null; see(new P$(1, "m"));'), ('the prototype is a number', BASE, 'P$.prototype = 5; see(new P$(1, "m"));'), ('an accessor on the prototype under a stored name', BASE, 'Object.defineProperty(P$.prototype, "x", { set(v) { out.push("setter " + v); }, get() { return "got"; }, configurable: true }); see(new P$(1, "m"));'), ('a read-only member on the prototype under a stored name', BASE, 'Object.defineProperty(P$.prototype, "y", { value: "fixed", writable: false }); try { see(new P$(1, "m")); } catch (e) { out.push("T:" + e.name); }'),
 ('classical inheritance', BASE, 'function K$(a, b, c) { P$.call(this, a, b); this.k = c; } K$.prototype = Object.create(P$.prototype); K$.prototype.constructor = K$; const o = new K$(1, "m", true); out.push(o instanceof P$, o instanceof K$); see(o);'), ('a class extends it', BASE, 'class K$ extends P$ { constructor() { super(1, "cls"); this.k = 2; } } const o = new K$(); out.push(o instanceof P$); see(o);'), ('Object.create of its prototype', BASE, 'const o = Object.create(P$.prototype); out.push(o instanceof P$); see(o);'),
 ('returns an object', 'function P$(a, b) { this.x = a; this.y = b; if (a === 9) return { other: 1 }; }', 'see(new P$(9, "r"));'), ('returns a primitive', 'function P$(a, b) { this.x = a; this.y = b; return 5; }', 'see(new P$(9, "r"));'), ('returns this early', 'function P$(a, b) { this.x = a; if (a === 9) return; this.y = b; }', 'see(new P$(9, "r"));'), ('new.target', 'function P$(a, b) { this.x = a; this.y = new.target === P$; }', 'see(new P$(9)); const o = {}; P$.call(o, 1); see(o);'),
 ('stores under a condition', 'function P$(a, b) { if (a > 1) this.big = true; this.x = a; if (b) this.y = b; }', 'see(new P$(2, "")); see(new P$(0, "z"));'), ('stores in another order by a condition', 'function P$(a, b) { if (a > 1) { this.y = b; this.x = a; } else { this.x = a; this.y = b; } }', 'see(new P$(2, "o"));'), ('stores in a loop by computed names', 'function P$(a, b) { for (const n of ["x", "y"]) this[n] = n === "x" ? a : b; }', 'see(new P$(2, "o"));'), ('stores twice', 'function P$(a, b) { this.x = 0; this.y = b; this.x = a; }', 'see(new P$(2, "o"));'), ('stores through a helper', 'function fill$(o, a, b) { o.x = a; o.y = b; } function P$(a, b) { fill$(this, a, b); }', 'see(new P$(2, "o"));'), ('stores through a method', 'function P$(a, b) { this.init(a, b); } P$.prototype.init = function (a, b) { this.x = a; this.y = b; };', 'see(new P$(2, "o"));'), ('Object.assign onto this', 'function P$(a, b) { Object.assign(this, { x: a, y: b }); }', 'see(new P$(2, "o"));'), ('defineProperty on this', 'function P$(a, b) { this.x = a; Object.defineProperty(this, "y", { value: b, enumerable: false }); }', 'see(new P$(2, "o"));'), ('deletes in the constructor', 'function P$(a, b) { this.x = a; this.y = b; delete this.x; }', 'see(new P$(2, "o"));'), ('freezes itself', 'function P$(a, b) { this.x = a; this.y = b; Object.freeze(this); }', 'const o = new P$(2, "o"); try { o.x = 5; } catch (e) { out.push("T:" + e.name); } see(o);'),
 ('this gets out in the constructor', 'const all$ = []; function P$(a, b) { all$.push(this); this.x = a; this.y = b; }', 'new P$(2, "o"); see(all$[all$.length - 1]); out.push(all$.length);'), ('this is read before it is stored to', 'function P$(a, b) { this.seen = String(this.x) + Object.keys(this).length; this.x = a; this.y = b; }', 'see(new P$(2, "o"));'), ('throws half way', 'function P$(a, b) { this.x = a; if (a === 9) throw new RangeError("half"); this.y = b; }', 'try { new P$(9); } catch (e) { out.push(e.name); }'), ('a closure over this', 'function P$(a, b) { this.x = a; this.y = b; this.get = () => this.x; }', 'const o = new P$(2, "o"); o.x = 3; out.push(o.get());'),
 ('members of other kinds', BASE, 'see(new P$("text", 5)); see(new P$(null, undefined)); see(new P$({ d: 1 }, [1])); see(new P$(0.5, -0));'), ('a member more, later', BASE, 'const o = new P$(1, "m"); o.z = 3; see(o);'), ('a member deleted, later', BASE, 'const o = new P$(1, "m"); delete o.x; see(o); o.x = 2; see(o);'), ('another prototype, later', BASE, 'const o = new P$(1, "m"); Object.setPrototypeOf(o, { up: 1 }); out.push(o.up, o instanceof P$); see(o);'), ('made an accessor, later', BASE, 'const o = new P$(1, "m"); Object.defineProperty(o, "x", { get: () => "acc", enumerable: true }); see(o);'),
 ('its prototype is asked for', BASE, 'const o = new P$(1, "m"); out.push(Object.getPrototypeOf(o) === P$.prototype, o.constructor === P$, o.__proto__ === P$.prototype, P$.prototype.isPrototypeOf(o), P$.prototype.constructor === P$);'), ('the function has members', BASE, 'P$.count = 0; P$.make = (a) => new P$(a, "made"); see(P$.make(4)); out.push(P$.name, P$.length, typeof P$.prototype);'), ('toString and valueOf from the prototype', BASE, 'P$.prototype.toString = function () { return "P(" + this.x + ")"; }; P$.prototype.valueOf = function () { return this.x; }; const o = new P$(4, "v"); out.push(`${o}`, o + 1, String(o));'), ('an enumerable member of the prototype in for-in', BASE, 'P$.prototype.inherited = 1; see(new P$(1, "m"));'),
 ('two hundred of them, and garbage', BASE, 'const l = []; for (let i = 0; i < 200; i++) l.push(new P$(i, "s" + i)); let junk = []; for (let i = 0; i < 100000; i++) junk.push({ i }); junk = null; out.push(l.reduce((s, o) => s + o.x + o.y.length, 0));'), ('structured by JSON and back', BASE, 'see(JSON.parse(JSON.stringify(new P$(1, "j"))));'), ('a spread and Object.assign of one', BASE, 'see({ ...new P$(1, "sp") }); see(Object.assign({}, new P$(2, "as")));'), ('a proxy of one, a proxy of the constructor', BASE, 'see(new Proxy(new P$(1, "px"), {})); see(new (new Proxy(P$, {}))(2, "pc"));'), ('recursion in the constructor', 'function P$(a, b) { this.x = a; this.y = a > 0 ? new P$(a - 1, b) : b; }', 'const o = new P$(2, "deep"); out.push(o.y.y.y); see(o.y);'),
]
print('"use strict";\nconst show = v => (v === null ? "null" : typeof v === "object" ? (Array.isArray(v) ? "[" + v.length + "]" : "{" + Object.keys(v).join() + "}") : typeof v === "function" ? "fn" : Object.is(v, -0) ? "-0" : typeof v + ":" + String(v));')
n = 0
for what, ctor, more in ROWS:
    n += 1
    s = '%s\nfunction row$() { const out = []; const see = o => { let inKeys = ""; for (const k in o) inKeys += k + ","; out.push(Object.keys(o).join() + "|" + show(o.x) + show(o.y) + "|" + (Object.getPrototypeOf(o) === P$.prototype) + (o instanceof P$) + "|" + JSON.stringify(o) + "|" + inKeys); }; try { see(new P$(1, "s")); see(new P$(2, "t")); %s see(new P$(3, "u")); } catch (e) { out.push("THROWS " + e.name); } return out.map(String).join(" ; "); }\nconsole.log("%d %s: " + row$());\n' % (ctor, more, n, what)
    print(s.replace('${', '\x00').replace('$', str(n)).replace('\x00', '${'), end='')
